{"path": "test_large2.py", "content": "def test_calc():
    from functools import lru_cache

    def count_upto(N, k):
        if N <=0:
            return 0
        s = str(N)
        n = len(s)
        @lru_cache(None)
        def dfs(pos, diff, mod, tight, started):
            if pos == n:
                if not started:
                    return 0
                if diff == 0 and mod == 0:
                    return 1
                return 0
            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(0, limit+1):
                ntight = tight and (d == limit)
                if not started and d == 0:
                    total += dfs(pos+1, diff, mod, ntight, False)
                else:
                    ndiff = diff + (1 if d % 2 == 0 else -1)
                    nmod = (mod * 10 + d) % k
                    total += dfs(pos+1, ndiff, nmod, ntight, True)
            return total
        return dfs(0, 0, 0, True, False)

    cases = [
        (33340762, 612987024, 1, 18196584),
        (36954768, 642296821, 14, 1240042),
        (17946863, 807558969, 17, 1319380),
        (19,50,2,6),
        (19,50,2,14),
    ]
    for low,high,k,exp in cases:
        dp = count_upto(high,k) - count_upto(low-1,k)
        print(f"{low},{high},{k} dp={dp} exp={exp} match={dp==exp}")
    assert False

